<div class="card"><h1>Edit Listing</h1><?php if($message): ?><div class="alert"><?= $message ?></div><?php endif; ?><form method="post"><label>Title</label><input name="title" value="<?= e($listing['title']) ?>" required><label>Description</label><textarea name="description" required><?= e($listing['description']) ?></textarea><label>Category</label><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$listing['category_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select><label>Condition</label><select name="condition"><?php foreach(['new'=>'New','like_new'=>'Like New','good'=>'Good','fair'=>'Fair'] as $value=>$label): ?><option value="<?= e($value) ?>" <?= $listing['condition']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><label>Starting Price</label><input type="number" step="0.01" name="starting_price" value="<?= e($listing['starting_price']) ?>" required><label>Reserve Price</label><input type="number" step="0.01" name="reserve_price" value="<?= e($listing['reserve_price']) ?>"><label>End</label><input type="datetime-local" name="end_datetime" value="<?= date('Y-m-d\\TH:i', strtotime($listing['end_datetime'])) ?>" required><button>Save if zero bids</button></form></div>
